import json
from datetime import datetime, date
class DateTimeEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, (datetime, date)):
            return obj.isoformat()
        return super().default(obj)
data = {'created': datetime(2023, 1, 1, 12, 0, 0)}
print(json.dumps(data, cls=DateTimeEncoder))

import json
from decimal import Decimal
from datetime import datetime
class UniversalEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, Decimal):
            return str(obj)
        if isinstance(obj, datetime):
            return obj.isoformat()
        if hasattr(obj, '__dict__'):
            return obj.__dict__
        return super().default(obj)
class Product:
    def __init__(self):
        self.name = 'Widget'
        self.price = Decimal('19.99')
data = {'item': Product(), 'created': datetime(2023, 6, 15)}
result = json.dumps(data, cls=UniversalEncoder)
print('"name"' in result and '"19.99"' in result)

import json
from json import JSONEncoder
def custom_encoder(obj):
    if isinstance(obj, frozenset):
        return list(obj)
    raise TypeError(f'Object of type {type(obj)} is not JSON serializable')
class MyEncoder(JSONEncoder):
    def default(self, obj):
        return custom_encoder(obj)
data = {'unique_items': frozenset([1, 2, 3])}
result = json.dumps(data, cls=MyEncoder)
print('1' in result and '3' in result)

import json
class Node:
    def __init__(self, value, children=None):
        self.value = value
        self.children = children or []
    def to_dict(self):
        return {'value': self.value, 'children': [c.to_dict() for c in self.children]}
tree = Node(1, [Node(2), Node(3, [Node(4)])])
serialized = json.dumps(tree, default=lambda o: o.to_dict())
obj = json.loads(serialized)
print(obj['children'][1]['children'][0]['value'])

